CREATE OR ALTER PROCEDURE usp_PartSale_Add
    @PartID        INT,
    @CustomerID    INT,          -- NULL for a walk-in customer
    @Quantity      INT,
    @SoldByStaffID INT,
    @NewPartSaleID INT OUTPUT,
    @Message VARCHAR(200) OUTPUT
AS
BEGIN
    SET @Message = '';

    IF @Quantity <= 0
    BEGIN
        SET @Message = 'Sell at least one.';
        RETURN;
    END

    DECLARE @SellPrice DECIMAL(7,2), @InStock INT;
    SELECT @SellPrice = SellPrice, @InStock = QtyInStock FROM Part
        WHERE PartID = @PartID;
    IF @SellPrice IS NULL
    BEGIN
        SET @Message = 'Choose a part.';
        RETURN;
    END

    -- Is there enough?  If not, refuse and stop.
    IF @InStock < @Quantity
    BEGIN
        SET @Message = 'Only ' + CAST(@InStock AS VARCHAR) + ' in stock.';
        RETURN;
    END

    -- Take the stock off.  The table's CHECK (QtyInStock >= 0) is the
    -- database's own backstop.
    UPDATE Part
    SET QtyInStock = QtyInStock - @Quantity
    WHERE PartID = @PartID;

    INSERT INTO PartSale (PartID, CustomerID, Quantity, UnitPrice,
        SoldByStaffID)
    VALUES (@PartID, @CustomerID, @Quantity, @SellPrice, @SoldByStaffID);

    SET @NewPartSaleID = SCOPE_IDENTITY();
END
GO

-- Sell 3 of part 5 (the 9-speed chain, 5 in stock) to a walk-in customer.
-- Run it once: it sells and 2 are left.  Run it again: only 2 in stock.
DECLARE @NewID INT, @Left INT, @Message VARCHAR(200);

EXEC usp_PartSale_Add
     @PartID = 5, @CustomerID = NULL, @Quantity = 3, @SoldByStaffID = 2,
     @NewPartSaleID = @NewID OUTPUT, @Message = @Message OUTPUT;

IF @Message = ''
BEGIN
    SELECT @Left = QtyInStock FROM Part WHERE PartID = 5;
    PRINT 'Sold. New sale number ' + CAST(@NewID AS VARCHAR)
        + '. Stock of part 5 is now '
        + CAST(@Left AS VARCHAR)
        + '.';
END
ELSE
BEGIN
    PRINT @Message;
END

CREATE OR ALTER PROCEDURE usp_PartSale_Refund
    @PartSaleID INT,
    @Message VARCHAR(200) OUTPUT
AS
BEGIN
    SET @Message = '';

    DECLARE @PartID INT, @Quantity INT;
    SELECT @PartID = PartID, @Quantity = Quantity
    FROM PartSale
    WHERE PartSaleID = @PartSaleID AND Status = 'Sold';
    IF @PartID IS NULL
    BEGIN
        SET @Message =
            'That sale has already been refunded, or does not exist.';
        RETURN;
    END

    UPDATE PartSale SET Status = 'Refunded' WHERE PartSaleID = @PartSaleID;
    -- stock goes back
    UPDATE Part SET QtyInStock = QtyInStock + @Quantity WHERE PartID = @PartID;
END
GO

-- Refund one sale by its number, then look at the sales of the last ten
-- days.  Run it once: the stock goes back up.  Run it again: refused.
DECLARE @ID INT, @Left INT, @From DATE, @To DATE, @Message VARCHAR(200);
-- put your sale number here
SET @ID = 9;

EXEC usp_PartSale_Refund @PartSaleID = @ID, @Message = @Message OUTPUT;

IF @Message = ''
BEGIN
    SELECT @Left = QtyInStock FROM Part WHERE PartID = 5;
    PRINT 'Refunded sale number ' + CAST(@ID AS VARCHAR)
        + '. Stock of part 5 is now '
        + CAST(@Left AS VARCHAR)
        + '.';
END
ELSE
BEGIN
    PRINT @Message;
END

SET @To = CAST(GETDATE() AS DATE);
SET @From = DATEADD(DAY, -10, @To);
EXEC usp_PartSale_GetByDateRange @FromDate = @From, @ToDate = @To;

CREATE OR ALTER PROCEDURE usp_PartOrder_Place
    @PartID          INT,
    @QtyOrdered      INT,
    @ExpectedOn      DATE,
    @PlacedByStaffID INT,
    @NewPartOrderID  INT OUTPUT,
    @Message VARCHAR(200) OUTPUT
AS
BEGIN
    SET @Message = '';
    IF @QtyOrdered <= 0
    BEGIN
        SET @Message = 'Order at least one.';
        RETURN;
    END

    INSERT INTO PartOrder (PartID, QtyOrdered, ExpectedOn, PlacedByStaffID)
    VALUES (@PartID, @QtyOrdered, @ExpectedOn, @PlacedByStaffID);
    SET @NewPartOrderID = SCOPE_IDENTITY();
END
GO

CREATE OR ALTER PROCEDURE usp_PartOrder_Receive
    @PartOrderID INT,
    @QtyReceived INT,
    @Message VARCHAR(200) OUTPUT
AS
BEGIN
    SET @Message = '';

    IF @QtyReceived < 0
    BEGIN
        SET @Message = 'The quantity received cannot be negative.';
        RETURN;
    END

    DECLARE @PartID INT;
    SELECT @PartID = PartID FROM PartOrder WHERE PartOrderID = @PartOrderID
        AND Status = 'Ordered';
    IF @PartID IS NULL
    BEGIN
        SET @Message = 'That order is not open.';
        RETURN;
    END

    -- Two changes that must both happen: the order is closed and the stock goes
    -- up.
    UPDATE PartOrder
    SET Status = 'Received', ReceivedOn = CAST(GETDATE() AS DATE),
        QtyReceived = @QtyReceived
    WHERE PartOrderID = @PartOrderID;

    UPDATE Part
    SET QtyInStock = QtyInStock + @QtyReceived
    WHERE PartID = @PartID;
END
GO

-- Order 10 more of part 5 from its supplier, expected in a week.
DECLARE @Expected DATE, @NewID INT, @Message VARCHAR(200);
SET @Expected = DATEADD(DAY, 7, CAST(GETDATE() AS DATE));

EXEC usp_PartOrder_Place
     @PartID = 5, @QtyOrdered = 10, @ExpectedOn = @Expected,
     @PlacedByStaffID = 1,
     @NewPartOrderID = @NewID OUTPUT, @Message = @Message OUTPUT;

IF @Message = ''
BEGIN
    PRINT 'Ordered. New order number ' + CAST(@NewID AS VARCHAR)
        + ', expected on ' + CAST(@Expected AS VARCHAR) + '.';
END
ELSE
BEGIN
    PRINT @Message;
END

-- The delivery arrives: receive one order by its number.
-- Run it once: the order closes and the stock goes up.  Run it again:
-- that order is not open.
DECLARE @ID INT, @Left INT, @Message VARCHAR(200);
-- put your order number here
SET @ID = 5;

EXEC usp_PartOrder_Receive
     @PartOrderID = @ID, @QtyReceived = 10, @Message = @Message OUTPUT;

IF @Message = ''
BEGIN
    SELECT @Left = QtyInStock FROM Part WHERE PartID = 5;
    PRINT 'Received order number ' + CAST(@ID AS VARCHAR)
        + '. Stock of part 5 is now '
        + CAST(@Left AS VARCHAR)
        + '.';
END
ELSE
BEGIN
    PRINT @Message;
END

CREATE OR ALTER PROCEDURE usp_PartOrder_Cancel
    @PartOrderID INT,
    @Message VARCHAR(200) OUTPUT
AS
BEGIN
    SET @Message = '';
    IF NOT EXISTS (SELECT * FROM PartOrder WHERE PartOrderID = @PartOrderID
        AND Status = 'Ordered')
    BEGIN
        SET @Message = 'Only an open order can be cancelled.';
        RETURN;
    END
    UPDATE PartOrder SET Status = 'Cancelled' WHERE PartOrderID = @PartOrderID
        AND Status = 'Ordered';
END
GO

-- Place an order for 6 of part 5, cancel it, then try to cancel it again.
-- Then list the orders that are still open.
DECLARE @Expected DATE, @NewID INT, @Message VARCHAR(200);
SET @Expected = DATEADD(DAY, 7, CAST(GETDATE() AS DATE));

EXEC usp_PartOrder_Place
     @PartID = 5, @QtyOrdered = 6, @ExpectedOn = @Expected,
     @PlacedByStaffID = 1,
     @NewPartOrderID = @NewID OUTPUT, @Message = @Message OUTPUT;
PRINT 'Placed order number ' + CAST(@NewID AS VARCHAR) + '.';

EXEC usp_PartOrder_Cancel @PartOrderID = @NewID, @Message = @Message OUTPUT;
IF @Message = ''
BEGIN
    PRINT 'Cancelled order number ' + CAST(@NewID AS VARCHAR) + '.';
END
ELSE
BEGIN
    PRINT @Message;
END

EXEC usp_PartOrder_Cancel @PartOrderID = @NewID, @Message = @Message OUTPUT;
IF @Message = ''
BEGIN
    PRINT 'The second cancel got through: the rule is broken.';
END
ELSE
BEGIN
    PRINT 'Second cancel refused: ' + @Message;
END

EXEC usp_PartOrder_GetOpen;

CREATE OR ALTER PROCEDURE usp_Part_Add
    @PartCode     VARCHAR(12),
    @Name         VARCHAR(60),
    @SupplierID   INT,
    @UnitCost     DECIMAL(7,2),
    @SellPrice    DECIMAL(7,2),
    @QtyInStock   INT,
    @ReorderLevel INT,
    @ReorderQty   INT,
    @NewPartID    INT OUTPUT,
    @Message VARCHAR(200) OUTPUT
AS
BEGIN
    SET @Message = '';
    IF EXISTS (SELECT * FROM Part WHERE PartCode = @PartCode)
    BEGIN
        SET @Message = 'That part code is already in use.';
        RETURN;
    END

    INSERT INTO Part (PartCode, Name, SupplierID, UnitCost, SellPrice,
        QtyInStock, ReorderLevel, ReorderQty)
    VALUES (@PartCode, @Name, @SupplierID, @UnitCost, @SellPrice, @QtyInStock,
        @ReorderLevel, @ReorderQty);
    SET @NewPartID = SCOPE_IDENTITY();
END
GO

CREATE OR ALTER PROCEDURE usp_Part_Update
    @PartID       INT,
    @Name         VARCHAR(60),
    @SupplierID   INT,
    @UnitCost     DECIMAL(7,2),
    @SellPrice    DECIMAL(7,2),
    @ReorderLevel INT,
    @ReorderQty   INT,
    @Message VARCHAR(200) OUTPUT
AS
BEGIN
    SET @Message = '';
    -- No QtyInStock here on purpose: stock only moves through sales, deliveries
    -- and refunds.
    UPDATE Part
    SET Name = @Name, SupplierID = @SupplierID, UnitCost = @UnitCost,
        SellPrice = @SellPrice,
        ReorderLevel = @ReorderLevel, ReorderQty = @ReorderQty
    WHERE PartID = @PartID;
END
GO

-- Every part, then only the parts that need reordering.
EXEC usp_Part_GetAll;
EXEC usp_Part_GetReorderList;

namespace BikeShop.Models
{
    // One part we stock.  Plain properties only.
    public class Part
    {
        public int PartID { get; set; }
        public string PartCode { get; set; }
        public string Name { get; set; }
        public int SupplierID { get; set; }
        public decimal UnitCost { get; set; }
        public decimal SellPrice { get; set; }
        public int QtyInStock { get; set; }
        public int ReorderLevel { get; set; }
        public int ReorderQty { get; set; }
    }
}

using System.Data;
using System.Data.SqlClient;
using BikeShop.Models;

namespace BikeShop.Data
{
    public static class PartData
    {
        // Every part.
        public static DataTable GetAll()
        {
            return Db.GetTable("usp_Part_GetAll");
        }

        #region GetReorderList
        // The parts whose stock has fallen to the reorder level or below.
        public static DataTable GetReorderList()
        {
            return Db.GetTable("usp_Part_GetReorderList");
        }
        #endregion

        // Saves a new part.  Returns "" if it worked, or the sentence to show
        // the user.
        public static string Add(Part part)
        {
            SqlParameter newID = Db.Out("@NewPartID");
            string message = Db.Run("usp_Part_Add",
                Db.P("@PartCode", part.PartCode),
                Db.P("@Name", part.Name),
                Db.P("@SupplierID", part.SupplierID),
                Db.P("@UnitCost", part.UnitCost),
                Db.P("@SellPrice", part.SellPrice),
                Db.P("@QtyInStock", part.QtyInStock),
                Db.P("@ReorderLevel", part.ReorderLevel),
                Db.P("@ReorderQty", part.ReorderQty),
                newID);
            if (message == "")
            {
                part.PartID = (int)newID.Value;
            }
            return message;
        }

        // No QtyInStock here: stock only changes through sales, deliveries and
        // refunds.
        public static string Update(Part part)
        {
            return Db.Run("usp_Part_Update",
                Db.P("@PartID", part.PartID),
                Db.P("@Name", part.Name),
                Db.P("@SupplierID", part.SupplierID),
                Db.P("@UnitCost", part.UnitCost),
                Db.P("@SellPrice", part.SellPrice),
                Db.P("@ReorderLevel", part.ReorderLevel),
                Db.P("@ReorderQty", part.ReorderQty));
        }
    }
}

using System;
using System.Data;
using System.Data.SqlClient;

namespace BikeShop.Data
{
    public static class PartOrderData
    {
        // Orders more of a part from its supplier.  Returns "" if it worked.
        // The procedure always wants the @NewPartOrderID output parameter, but
        // this screen does not need the number.
        public static string Place(int partID, int qtyOrdered,
            DateTime expectedOn, int placedByStaffID)
        {
            SqlParameter newID = Db.Out("@NewPartOrderID");
            return Db.Run("usp_PartOrder_Place",
                Db.P("@PartID", partID),
                Db.P("@QtyOrdered", qtyOrdered),
                Db.P("@ExpectedOn", expectedOn.Date),
                Db.P("@PlacedByStaffID", placedByStaffID),
                newID);
        }

        #region Receive
        // One call: the order closes AND the stock goes up.
        public static string Receive(int partOrderID, int qtyReceived)
        {
            return Db.Run("usp_PartOrder_Receive",
                Db.P("@PartOrderID", partOrderID),
                Db.P("@QtyReceived", qtyReceived));
        }
        #endregion

        // Cancels an order that has not arrived.
        public static string Cancel(int partOrderID)
        {
            return Db.Run("usp_PartOrder_Cancel",
                Db.P("@PartOrderID", partOrderID));
        }

        // The orders still waiting for a delivery.
        public static DataTable GetOpen()
        {
            return Db.GetTable("usp_PartOrder_GetOpen");
        }

        // Every order, open or closed.
        public static DataTable GetAll()
        {
            return Db.GetTable("usp_PartOrder_GetAll");
        }
    }
}

using System;
using System.Data;
using System.Data.SqlClient;

namespace BikeShop.Data
{
    public static class PartSaleData
    {
        #region Add
        // customerID 0 means a walk-in customer, who is saved as NULL.  The
        // procedure refuses the sale if stock is short.
        // Returns "" if it worked.  The procedure always wants the
        // @NewPartSaleID output parameter, but this screen does not need the
        // number.
        public static string Add(int partID, int customerID, int quantity,
            int soldByStaffID)
        {
            object customer = DBNull.Value;
            if (customerID > 0)
            {
                customer = customerID;
            }
            SqlParameter newID = Db.Out("@NewPartSaleID");
            return Db.Run("usp_PartSale_Add",
                Db.P("@PartID", partID),
                Db.P("@CustomerID", customer),
                Db.P("@Quantity", quantity),
                Db.P("@SoldByStaffID", soldByStaffID),
                newID);
        }
        #endregion

        // Takes a sale back and puts the parts back in stock.
        public static string Refund(int partSaleID)
        {
            return Db.Run("usp_PartSale_Refund",
                Db.P("@PartSaleID", partSaleID));
        }

        // The sales between two dates.
        public static DataTable GetByDateRange(DateTime fromDate,
            DateTime toDate)
        {
            return Db.GetTable("usp_PartSale_GetByDateRange",
                Db.P("@FromDate", fromDate.Date), Db.P("@ToDate", toDate.Date));
        }
    }
}

using System;
using System.Collections.Generic;
using System.Data;
using System.Drawing;
using System.Windows.Forms;
using BikeShop.Data;
using BikeShop.Models;

namespace BikeShop.Forms
{
    public partial class frmPartEdit : Form
    {
        // 0 = adding; otherwise the part being edited
        private readonly int partID;

        // Add a part
        public frmPartEdit()
        {
            InitializeComponent();
        }

        // Edit a part: the values come from the row the grid already holds
        public frmPartEdit(DataRow part)
        {
            InitializeComponent();
            partID = (int)part["PartID"];
            txtCode.Text = (string)part["PartCode"];
            txtName.Text = (string)part["Name"];
            nudUnitCost.Value = (decimal)part["UnitCost"];
            nudSellPrice.Value = (decimal)part["SellPrice"];
            nudReorderLevel.Value = (int)part["ReorderLevel"];
            nudReorderQty.Value = (int)part["ReorderQty"];
            // kept until the supplier list has loaded
            cboSupplier.Tag = part["SupplierID"];
        }

        private void frmPartEdit_Load(object sender, EventArgs e)
        {
            // The boxes stop typing at the length the database column holds.
            txtCode.MaxLength = 12;
            txtName.MaxLength = 60;

            cboSupplier.DisplayMember = "Name";
            cboSupplier.ValueMember = "SupplierID";
            cboSupplier.DataSource = SupplierData.GetAll();

            if (partID == 0)
            {
                Text = "Add a part";
                return;
            }

            Text = "Edit part";
            cboSupplier.SelectedValue = cboSupplier.Tag;
            // the code is the part's name on the shelf: it does not change
            txtCode.Enabled = false;
            lblStock.Text =
                "Stock changes only through sales, refunds and deliveries.";
            nudStock.Visible = false;
        }

        #region Save
        private void btnSave_Click(object sender, EventArgs e)
        {
            // Check what was typed, one problem at a time: show the first and
            // put the cursor there.
            // The number boxes need no check: none of them goes below 0, and
            // the reorder quantity starts at 1.
            if (txtCode.Text.Trim() == "")
            {
                Msg.Problem("Type the part code.");
                txtCode.Focus();
                return;
            }
            if (txtName.Text.Trim() == "")
            {
                Msg.Problem("Type the part's name.");
                txtName.Focus();
                return;
            }
            if (cboSupplier.SelectedValue == null)
            {
                Msg.Problem("Choose the part's supplier.");
                cboSupplier.Focus();
                return;
            }

            Part part = new Part();
            part.PartID = partID;
            part.PartCode = txtCode.Text.Trim().ToUpper();
            part.Name = txtName.Text.Trim();
            part.SupplierID = (int)cboSupplier.SelectedValue;
            part.UnitCost = nudUnitCost.Value;
            part.SellPrice = nudSellPrice.Value;
            part.QtyInStock = (int)nudStock.Value;
            part.ReorderLevel = (int)nudReorderLevel.Value;
            part.ReorderQty = (int)nudReorderQty.Value;

            string message;
            if (partID == 0)
            {
                message = PartData.Add(part);
            }
            else
            {
                message = PartData.Update(part);
            }
            if (message != "")
            {
                // e.g. that part code is already in use
                Msg.Problem(message);
                return;
            }
            DialogResult = DialogResult.OK;
        }
        #endregion
    }
}

using System;
