private void LoadParts()
{
    // empty the grid first, so the two lists never mix their columns
    dgvParts.DataSource = null;
    dgvParts.Columns.Clear();
    if (reorderOnly)
    {
        dgvParts.DataSource = PartData.GetReorderList();
        btnReorderList.Text = "Show all parts";
    }
    else
    {
        dgvParts.DataSource = PartData.GetAll();
        btnReorderList.Text = "Reorder list";
    }
    Grid.Tidy(dgvParts, "PartID", "SupplierID");
}

// The grid raises this when it has finished filling: the moment to tint
// the parts that are low on stock.
private void dgvParts_DataBindingComplete(object sender,
    DataGridViewBindingCompleteEventArgs e)
{
    if (reorderOnly)
    {
        // every part on the reorder list is low, so only the full list
        // is tinted
        return;
    }

    foreach (DataGridViewRow row in dgvParts.Rows)
    {
        int inStock = Convert.ToInt32(row.Cells["QtyInStock"].Value);
        int reorderLevel =
            Convert.ToInt32(row.Cells["ReorderLevel"].Value);
        if (inStock <= reorderLevel)
        {
            row.DefaultCellStyle.BackColor = Color.MistyRose;
        }
        else
        {
            row.DefaultCellStyle.BackColor = Color.White;
        }
    }
}

private void btnReorderList_Click(object sender, EventArgs e)
{
    reorderOnly = !reorderOnly;
    LoadParts();
}

