CREATE OR ALTER PROCEDURE usp_Hire_CheckOut
    @HireID INT,
    @Message VARCHAR(200) OUTPUT
AS
BEGIN
    SET @Message = '';
    IF NOT EXISTS (SELECT * FROM Hire WHERE HireID = @HireID
        AND Status = 'Booked')
    BEGIN
        SET @Message = 'Only a booked hire can be checked out.';
        RETURN;
    END
    UPDATE Hire SET Status = 'Out' WHERE HireID = @HireID AND Status = 'Booked';
END
GO

CREATE OR ALTER PROCEDURE usp_Hire_Return
    @HireID INT,
    @Message VARCHAR(200) OUTPUT
AS
BEGIN
    SET @Message = '';
    IF NOT EXISTS (SELECT * FROM Hire WHERE HireID = @HireID AND Status = 'Out')
    BEGIN
        SET @Message = 'Only a hire that is out can be returned.';
        RETURN;
    END
    UPDATE Hire SET Status = 'Returned' WHERE HireID = @HireID
        AND Status = 'Out';
END
GO

-- Hand bike 1 to Jack O'Hare: hire 4 is booked.  Then try hire 1, which
-- came back weeks ago.
DECLARE @Message VARCHAR(200);

EXEC usp_Hire_CheckOut @HireID = 4, @Message = @Message OUTPUT;
IF @Message = ''
BEGIN
    PRINT 'Hire 4 is out.';
END
ELSE
BEGIN
    PRINT 'Hire 4: ' + @Message;
END

EXEC usp_Hire_CheckOut @HireID = 1, @Message = @Message OUTPUT;
PRINT 'Hire 1: ' + @Message;

-- Bike 1 comes back: hire 4 is out.  Run it once: returned.  Run it
-- again: only a hire that is out can be returned.
DECLARE @Message VARCHAR(200);

EXEC usp_Hire_Return @HireID = 4, @Message = @Message OUTPUT;
IF @Message = ''
BEGIN
    PRINT 'Hire 4 is returned.';
END
ELSE
BEGIN
    PRINT 'Hire 4: ' + @Message;
END

CREATE OR ALTER PROCEDURE usp_Hire_Cancel
    @HireID INT,
    @Message VARCHAR(200) OUTPUT
AS
BEGIN
    SET @Message = '';
    IF NOT EXISTS (SELECT * FROM Hire WHERE HireID = @HireID
        AND Status = 'Booked')
    BEGIN
        SET @Message = 'Only a booked hire can be cancelled.';
        RETURN;
    END
    UPDATE Hire SET Status = 'Cancelled' WHERE HireID = @HireID
        AND Status = 'Booked';
END
GO

-- Cancel hire 5, a booked hire of bike 1, then try to cancel it again.
-- Then look at the whole history of bike 1.
DECLARE @Message VARCHAR(200);

EXEC usp_Hire_Cancel @HireID = 5, @Message = @Message OUTPUT;
IF @Message = ''
BEGIN
    PRINT 'Cancelled hire number 5.';
END
ELSE
BEGIN
    PRINT 'Hire 5: ' + @Message;
END

EXEC usp_Hire_Cancel @HireID = 5, @Message = @Message OUTPUT;
IF @Message = ''
BEGIN
    PRINT 'The second cancel got through: the rule is broken.';
END
ELSE
BEGIN
    PRINT 'Second cancel refused: ' + @Message;
END

